### Cache at Every Layer

#### HTTP Caching Headers

```js
// Cache static assets for 1 year (content-hashed filenames)
app.use('/assets', express.static('public/assets', {
  maxAge: '1y',
  immutable: true // Tells browser: never recheck this URL
}));

// Cache API responses for 5 minutes, allow stale for 30s
app.get('/api/products', (req, res) => {
  res.set('Cache-Control', 'public, max-age=300, stale-while-revalidate=30');
  res.json(products);
});

// Never cache personalised or auth-required responses
app.get('/api/profile', authenticate, (req, res) => {
  res.set('Cache-Control', 'private, no-store');
  res.json(req.user);
});
```

#### Database Query Caching

```js
// Cache expensive aggregation results
async function getLeaderboard() {
  const cacheKey = 'leaderboard:weekly';
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);

  // This query might scan millions of rows
  const results = await db.query(`
    SELECT user_id, SUM(score) as total
    FROM submissions
    WHERE created_at > NOW() - INTERVAL '7 days'
    GROUP BY user_id
    ORDER BY total DESC
    LIMIT 100
  `);

  // Cache for 10 minutes
  await redis.setex(cacheKey, 600, JSON.stringify(results));
  return results;
}
```

